command:
set -u; echo HOST=$(hostname) USER=$(whoami); echo '===REPO==='; cd ~/frankenstein-repo && printf 'HEAD=' && git rev-parse --short HEAD && printf 'BRANCH=' && git branch --show-current && git status --short | sed -n '1,40p'; echo '===TITAN-CODE==='; rg -n -i --glob '*.py' --glob '*.md' --glob '*.json' 'titan[_ -]?(mx|x)|hypermirror|memoryx|memory x' ~/frankenstein-repo ~/aicore/opt/aicore ~/.claude/star 2>/dev/null | head -220; echo '===VOICE-PERSON==='; rg -n -i --glob '*.py' --glob '*.md' --glob '*.json' 'gespraech|gespräch|speaker|owner|andreas|gabriel|person_id|user_id|identity.*person|retriev' ~/frankenstein-repo/scripts /var/lib/entityos/voice ~/.claude/star 2>/dev/null | head -260; echo '===DB-SCHEMA==='; python3 - <<'PY'
import sqlite3, pathlib
for p in [pathlib.Path.home()/'.local/share/agentzero/unified.db', pathlib.Path('/var/lib/entityos/data/unified.db')]:
    if not p.exists(): continue
    print('DB',p)
    try:
      c=sqlite3.connect(f'file:{p}?mode=ro', uri=True)
      rows=c.execute("select name,sql from sqlite_master where type='table' and (lower(name) like '%titan%' or lower(name) like '%memory%' or lower(name) like '%person%' or lower(name) like '%retriev%' or lower(name) like '%speaker%') order by name").fetchall()
      for n,s in rows[:120]: print(n, (s or '')[:320].replace('\n',' '))
      c.close()
    except Exception as e: print('DBERR',repr(e))
PY
